 {let mut pass=encoder.begin_render_pass(&RenderPassDescriptor {label:None,color_attachments:&[Some(RenderPassColorAttachment {view:&color_view,depth_slice:None,resolve_target:None,ops:Operations {load:LoadOp::Clear(Color {r:0.2,g:0.4,b:0.6,a:0.8}),store:StoreOp::Store}})],depth_stencil_attachment:Some(RenderPassDepthStencilAttachment {view:&depth_view,depth_ops:Some(Operations {load:LoadOp::Clear(0.0),store:StoreOp::Store}),stencil_ops:None}),..Default::default()});for row in 0..4 {pass.set_viewport(0.,row as f32,256.,1.,0.,1.);pass.set_scissor_rect(0,row,256,1);pass.set_pipeline(&depth_only);pass.draw(0..3,0..1);if row>=2 {pass.set_pipeline(&back);pass.draw(0..3,0..1);}if row%2==1 {pass.set_pipeline(&transparent);pass.draw(0..3,0..1);}}}

 encoder.copy_texture_to_buffer(TexelCopyTextureInfo {texture:&color,mip_level:0,origin:Origin3d::ZERO,aspect:TextureAspect::All},TexelCopyBufferInfo {buffer:&read,layout:TexelCopyBufferLayout {offset:0,bytes_per_row:Some(1024),rows_per_image:Some(4)}},size);queue.submit([encoder.finish()]);let(tx,rx)=mpsc::channel();read.slice(..).map_async(MapMode::Read,move|result|tx.send(result).unwrap());device.poll(PollType::wait_indefinitely()).unwrap();rx.recv().unwrap().unwrap();let data=read.slice(..).get_mapped_range();let mut maximum_error=0i32;
 for row in 0..4usize {for x in 0..256usize {let a=x as f64/255.;let background=if row>=2 && x<=229 {[0.,0.,1.,1.]} else {[0.2,0.4,0.6,0.8]};let expected=if row%2==1 {[a+background[0]*(1.-a),background[1]*(1.-a),background[2]*(1.-a),a*a+background[3]*(1.-a)]} else {background};for c in 0..4 {let reference=(expected[c]*255.).round() as i32;let actual=data[(row*256+x)*4+c] as i32;let error=(actual-reference).abs();maximum_error=maximum_error.max(error);assert!(error<=1,"row{row} alpha{x} channel{c}: actual{actual} expected{reference}");}}}
let threshold_cases=256;let midpoint_alpha=data[(256+128)*4+3];drop(data);read.unmap();let receipt=serde_json::json!({"passed":true,"complete":false,"adapter":info.name,"backend":format!("{:?}",info.backend),"actual_raster_pixels":1024,"channels_checked":4096,"maximum_unorm_byte_error":maximum_error,"native_midpoint_alpha":midpoint_alpha,"depth_behavior_cases":512,"depth_threshold_cases":threshold_cases,"quantized_depth_reference":229,"color_write_suppression_pixels":512,"alpha_test_enabled_on_blended_phase":false,"source_factors":"SRCALPHA for color and alpha","destination_factors":"INVSRCALPHA for color and alpha","limits":["Actual Vulkan raster uses production blend, depth-write and color-write helpers; first stage strict alpha threshold229/255, second stage alpha disabled; RGBA8 checked within one byte.","Original D3D framebuffer quantization, scene draw ordering, full alpha-state persistence and native depth comparison initialization remain open."]});std::fs::write("logs/selector7-depth-gpu.json",serde_json::to_vec_pretty(&receipt).unwrap()).unwrap();println!("Native selector7 depth GPU1024pixels4096channels maxbyteerror{maximum_error} separatealpha{midpoint_alpha}");
